/* Organizational hierarchy is stored only by position â†’ parent position.
   Roles and people describe a position; neither one creates a reporting line. */
(() => {
  'use strict';
  const E = window.bamcoEnterprise;
  if (!E) return;
  const { q, esc, fetchRows, rpc, removeRows, setBusy, notify } = E;
  const model = { roles: [], positions: [], assignments: [], loaded: false, scoped: false };
  let loading = null;
  const root = () => q('#organizationFeatureRoot');
  // Editing the tree is a feature action, not a role-name shortcut.  The
  // server-side save RPC makes the same decision before it mutates a position.
  const canManageStructure = () => window.BamcoAccess?.can?.('organization', 'edit') === true
    || window.BamcoAccess?.can?.('organization', 'manage_access') === true;
  const role = id => model.roles.find(item => String(item.id) === String(id));
  const position = id => model.positions.find(item => String(item.id) === String(id));
  const activeAssignment = positionId => {
    const today = new Date().toISOString().slice(0, 10);
    return model.assignments.find(item => String(item.position_id) === String(positionId)
      && item.is_primary
      && String(item.valid_from || '0000-01-01').slice(0, 10) <= today
      && (!item.valid_to || String(item.valid_to).slice(0, 10) > today));
  };
  function organizationProfiles() {
    const people = canManageStructure()
      ? (window.BamcoProfiles?.list?.() || state.profiles || [])
      : (window.bamcoOrganizationAccess?.people?.() || []);
    const byId = new Map();
    for (const person of [state.profile, ...people].filter(Boolean)) {
      if (person.id) byId.set(String(person.id), person);
    }
    return byId;
  }
  const personLabel = (userId, profiles = organizationProfiles()) => {
    const person = profiles.get(String(userId));
    return person?.display_name || person?.full_name || person?.email || E.personName(userId);
  };
  const positionLabel = item => {
    const assigned = activeAssignment(item.id);
    return `${item.title} â€” ${assigned ? personLabel(assigned.user_id) : 'Ø¨Ø¯ÙˆÙ† ÙØ±Ø¯ Ø´Ø§ØºÙ„'}`;
  };
  const initial = (item, profiles) => esc(String(personLabel(activeAssignment(item.id)?.user_id, profiles) || item.title || 'Ø³').trim().charAt(0) || 'Ø³');
  const currentSession = (userId, snapshot) => state.user?.id === userId && !!state.token &&
    (!snapshot || window.bamcoAuth?.isCurrent?.(snapshot) !== false);

  function userOrganization(userId) {
    const today = new Date().toISOString().slice(0, 10);
    const assignment = model.assignments.find(item => String(item.user_id) === String(userId)
      && item.is_primary
      && String(item.valid_from || '0000-01-01').slice(0, 10) <= today
      && (!item.valid_to || String(item.valid_to).slice(0, 10) > today));
    const assignedPosition = assignment && position(assignment.position_id);
    return assignedPosition ? { assignment, position: assignedPosition, role: role(assignedPosition.role_id) } : null;
  }

  function sortPositions(left, right) {
    const level = Number(role(right.role_id)?.level_no || 0) - Number(role(left.role_id)?.level_no || 0);
    return level || String(left.title).localeCompare(String(right.title), 'fa');
  }

  function childrenOf(parentId) {
    return model.positions
      .filter(item => String(item.parent_position_id || '') === String(parentId || ''))
      .sort(sortPositions);
  }

  function isDescendant(candidateId, ancestorId) {
    let cursor = position(candidateId);
    const guard = new Set();
    while (cursor?.parent_position_id && !guard.has(String(cursor.id))) {
      guard.add(String(cursor.id));
      if (String(cursor.parent_position_id) === String(ancestorId)) return true;
      cursor = position(cursor.parent_position_id);
    }
    return false;
  }

  function node(item, rendered, depth = 1, lineage = new Set()) {
    const itemId = String(item.id);
    if (lineage.has(itemId) || rendered.has(itemId)) return null;
    rendered.add(itemId);
    const nextLineage = new Set(lineage);
    nextLineage.add(itemId);
    const children = childrenOf(item.id)
      .filter(child => !nextLineage.has(String(child.id)))
      .map(child => node(child, rendered, depth + 1, nextLineage))
      .filter(Boolean);
    const x = children.length
      ? children.reduce((sum, child) => sum + child.x, 0) / children.length
      : rendered.leafIndex++;
    rendered.maxDepth = Math.max(rendered.maxDepth, depth);
    return { item, children, depth, x };
  }

  function treeLayout() {
    const rendered = new Set();
    rendered.leafIndex = 0;
    rendered.maxDepth = 1;
    const roots = model.positions
      .filter(item => !item.parent_position_id || !position(item.parent_position_id))
      .sort(sortPositions);
    const branches = roots.map(item => node(item, rendered)).filter(Boolean);
    // Invalid cyclic data must not make the rest of the hierarchy disappear.
    // Each unresolved component is attached once under the common company root.
    for (const item of model.positions.sort(sortPositions)) {
      if (!rendered.has(String(item.id))) {
        const branch = node(item, rendered);
        if (branch) branches.push(branch);
      }
    }
    return { branches, leaves: Math.max(rendered.leafIndex, 1), maxDepth: rendered.maxDepth };
  }

  function chart() {
    const layout = treeLayout();
    const profiles = organizationProfiles();
    // A chart card owns both the person's information and its connection
    // anchors.  Keeping these dimensions in the layout (rather than only in
    // CSS) makes every connector terminate at a card edge, never in its text.
    const cardWidth = 262;
    const cardHeight = 136;
    const nodeGap = 332;
    const margin = Math.ceil(cardWidth / 2) + 53;
    const usedWidth = Math.max(0, (layout.leaves - 1) * nodeGap);
    const width = Math.max(700, usedWidth + margin * 2);
    const firstX = (width - usedWidth) / 2;
    const firstY = 30;
    const levelGap = 230;
    const height = Math.max(250, firstY + (layout.maxDepth - 1) * levelGap + cardHeight + 54);
    const point = entry => ({ x: Math.round(firstX + entry.x * nodeGap), y: firstY + (entry.depth - 1) * levelGap });
    const links = [];
    const cards = [];
    const draw = (entry, parent = null) => {
      const target = point(entry);
      if (parent) {
        const source = point(parent);
        const sourceY = source.y + cardHeight;
        const targetY = target.y;
        const middle = Math.round((sourceY + targetY) / 2);
        links.push(`<path class="org-chart-link" data-org-link-from="${parent.item.id}" data-org-link-to="${entry.item.id}" d="M ${source.x} ${sourceY} V ${middle} H ${target.x} V ${targetY}"/>`);
      }
      const assigned = activeAssignment(entry.item.id);
      const orgRole = role(entry.item.role_id);
      const person = assigned ? personLabel(assigned.user_id, profiles) : '';
      const avatar = assigned
        ? `<span class="org-chart-avatar" data-profile-photo="${esc(assigned.user_id)}" aria-label="ØªØµÙˆÛŒØ± Ù¾Ø±ÙˆÙØ§ÛŒÙ„ ${esc(person)}">${initial(entry.item, profiles)}</span>`
        : '<span class="org-chart-avatar org-chart-avatar-empty" aria-hidden="true"></span>';
      const copy = `${avatar}<span class="org-chart-copy"><b>${esc(entry.item.title)}</b>${assigned ? `<small>${esc(person)}</small>` : ''}<em>${esc(orgRole?.title || 'Ø¨Ø¯ÙˆÙ† Ù†Ù‚Ø´')}</em></span>`;
      const parentId = entry.item.parent_position_id == null ? '' : String(entry.item.parent_position_id);
      const attributes = `data-org-parent="${esc(parentId)}" style="left:${target.x}px;top:${target.y}px"`;
      const label = assigned ? `${entry.item.title}ØŒ ${person}` : entry.item.title;
      cards.push(canManageStructure()
        ? `<button type="button" class="org-chart-node org-chart-card" data-org-edit="${entry.item.id}" ${attributes} aria-label="ÙˆÛŒØ±Ø§ÛŒØ´ ${esc(label)}">${copy}</button>`
        : `<div class="org-chart-node org-chart-card org-chart-node-readonly" ${attributes} role="treeitem" aria-label="${esc(label)}">${copy}</div>`);
      entry.children.forEach(child => draw(child, entry));
    };
    layout.branches.forEach(branch => draw(branch));
    return `<div class="organization-chart-canvas" role="tree" style="width:${width}px;height:${height}px"><svg class="org-chart-links" viewBox="0 0 ${width} ${height}" aria-hidden="true">${links.join('')}</svg>${cards.join('')}</div>`;
  }

  function positionDialog() {
    if (!canManageStructure()) return '';
    return `<dialog id="organizationPositionDialog" class="modal enterprise-modal"><form id="organizationPositionForm"><div class="modal-head"><h3 id="organizationPositionDialogTitle">Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø¬Ø¯ÛŒØ¯</h3><button type="button" data-org-close>Ã—</button></div><input type="hidden" name="id"><div class="form-grid"><label class="span-2">Ø¹Ù†ÙˆØ§Ù† Ø³Ù…Øª<input name="title" required placeholder="Ù…Ø«Ù„Ø§Ù‹ Ø±Ø¦ÛŒØ³ Ø¨Ø±Ù†Ø§Ù…Ù‡â€ŒØ±ÛŒØ²ÛŒ"></label><label>Ù†Ù‚Ø´ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ<select name="role_id" required></select></label><label>Ø¨Ø§Ù„Ø§Ø¯Ø³Øª Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ<select name="parent_position_id"><option value="">Ø¨Ø¯ÙˆÙ† Ø¨Ø§Ù„Ø§Ø¯Ø³Øª</option></select></label><label class="span-2">ÙØ±Ø¯ Ø´Ø§ØºÙ„ Ø¯Ø± Ø§ÛŒÙ† Ø¬Ø§ÛŒÚ¯Ø§Ù‡<select name="user_id"><option value="">Ø¨Ø¯ÙˆÙ† ÙØ±Ø¯ Ø´Ø§ØºÙ„</option></select></label></div><div class="modal-actions organization-position-actions"><button type="button" class="danger hidden" data-org-delete>Ø­Ø°Ù Ø¬Ø§ÛŒÚ¯Ø§Ù‡</button><button type="button" class="ghost" data-org-close>Ø§Ù†ØµØ±Ø§Ù</button><button type="submit" class="primary">Ø°Ø®ÛŒØ±Ù‡ Ø¬Ø§ÛŒÚ¯Ø§Ù‡</button></div></form></dialog>`;
  }

  function render() {
    const host = root();
    if (!host) return;
    const editor = canManageStructure();
    host.innerHTML = `<div class="feature-toolbar enterprise-toolbar"><div><h3>Ø³Ø§Ø®ØªØ§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3></div><div class="feature-toolbar-actions"><button type="button" class="ghost" data-org-home data-home-action>Ø¨Ø§Ø²Ú¯Ø´Øª Ø¨Ù‡ Ø®Ø§Ù†Ù‡</button>${editor ? '<button type="button" class="primary" data-org-action="position">ï¼‹ Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø¬Ø¯ÛŒØ¯</button>' : ''}</div></div>
      <div class="enterprise-grid organization-grid"><section class="panel organization-chart-panel"><div class="panel-head"><h3>Ù†Ù…ÙˆØ¯Ø§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ</h3></div><div class="organization-chart" aria-label="Ù†Ù…ÙˆØ¯Ø§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ">${model.positions.length ? chart() : `<div class="empty">${editor ? 'Ø¨Ø±Ø§ÛŒ Ø´Ø±ÙˆØ¹ØŒ Â«Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø¬Ø¯ÛŒØ¯Â» Ø±Ø§ Ø¨Ø²Ù†ÛŒØ¯.' : 'Ø¯Ø± Ø­Ø§Ù„ Ø­Ø§Ø¶Ø± Ø¬Ø§ÛŒÚ¯Ø§Ù‡ÛŒ Ø¯Ø± Ù…Ø­Ø¯ÙˆØ¯Ù‡Ù” Ù†Ø¸Ø§Ø±Øª Ø´Ù…Ø§ Ø«Ø¨Øª Ù†Ø´Ø¯Ù‡ Ø§Ø³Øª.'}</div>`}</div></section></div>${positionDialog()}`;
    if (editor) bindPositionForm();
    void window.bamcoMedia?.avatars?.(host.querySelector('.organization-chart'), [...organizationProfiles().values()]);
    bind();
  }

  function fillPositionForm(current = null) {
    const form = q('#organizationPositionForm');
    if (!form) return;
    form.elements.role_id.innerHTML = model.roles.filter(item => item.active)
      .map(item => `<option value="${item.id}">${esc(item.title)}</option>`).join('');
    form.elements.parent_position_id.innerHTML = '<option value="">Ø¨Ø¯ÙˆÙ† Ø¨Ø§Ù„Ø§Ø¯Ø³Øª</option>' + model.positions
      .filter(item => item.active && String(item.id) !== String(current?.id) && !isDescendant(item.id, current?.id))
      .sort(sortPositions)
      .map(item => `<option value="${item.id}">${esc(positionLabel(item))}</option>`).join('');
    form.elements.user_id.innerHTML = '<option value="">Ø¨Ø¯ÙˆÙ† ÙØ±Ø¯ Ø´Ø§ØºÙ„</option>' + (state.profiles || [])
      .filter(item => item.active !== false)
      .map(item => `<option value="${item.id}">${esc(item.display_name || item.full_name || item.email)}</option>`).join('');
    form.elements.id.value = current?.id || '';
    form.elements.title.value = current?.title || '';
    form.elements.role_id.value = current?.role_id ? String(current.role_id) : (form.elements.role_id.options[0]?.value || '');
    form.elements.parent_position_id.value = current?.parent_position_id ? String(current.parent_position_id) : '';
    form.elements.user_id.value = current ? (activeAssignment(current.id)?.user_id || '') : '';
    q('#organizationPositionDialogTitle').textContent = current ? 'ÙˆÛŒØ±Ø§ÛŒØ´ Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ' : 'Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø¬Ø¯ÛŒØ¯';
    const remove = q('[data-org-delete]', form);
    remove.dataset.orgDelete = current?.id || '';
    remove.classList.toggle('hidden', !current);
  }

  function openPosition(id = null) {
    if (!canManageStructure()) return;
    const form = q('#organizationPositionForm');
    if (!form) return;
    form.reset();
    fillPositionForm(id ? position(id) : null);
    q('#organizationPositionDialog').showModal();
  }

  function createsCycle(positionId, parentId) {
    let cursor = parentId;
    const guard = new Set();
    while (cursor) {
      if (String(cursor) === String(positionId) || guard.has(String(cursor))) return true;
      guard.add(String(cursor));
      cursor = position(cursor)?.parent_position_id || null;
    }
    return false;
  }

  async function savePosition(event) {
    event.preventDefault();
    event.stopPropagation();
    if (!canManageStructure()) return;
    const form = event.currentTarget?.id === 'organizationPositionForm' ? event.currentTarget : q('#organizationPositionForm');
    if (!form) return;
    const button = q('[type=submit]', form);
    const id = form.elements.id.value;
    const actorId = state.user?.id;
    const snapshot = window.bamcoAuth?.snapshot?.();
    if (!actorId) return notify('Ù†Ø´Ø³Øª Ú©Ø§Ø±Ø¨Ø±ÛŒ Ù…Ø¹ØªØ¨Ø± Ù†ÛŒØ³ØªØ› ØµÙØ­Ù‡ Ø±Ø§ Ø¯ÙˆØ¨Ø§Ø±Ù‡ Ø¨Ø§Ø² Ú©Ù†ÛŒØ¯.', true);
    const parentId = form.elements.parent_position_id.value ? Number(form.elements.parent_position_id.value) : null;
    if (id && createsCycle(id, parentId)) return notify('Ù†Ù…ÛŒâ€ŒØªÙˆØ§Ù† ÛŒÚ© Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø±Ø§ Ø²ÛŒØ±Ù…Ø¬Ù…ÙˆØ¹Ù‡Ù” Ø®ÙˆØ¯Ø´ ÛŒØ§ ÛŒÚ©ÛŒ Ø§Ø² Ø²ÛŒØ±Ù…Ø¬Ù…ÙˆØ¹Ù‡â€ŒÙ‡Ø§ÛŒØ´ Ù‚Ø±Ø§Ø± Ø¯Ø§Ø¯.', true);
    const payload = {
      p_title: form.elements.title.value.trim(),
      p_role_id: Number(form.elements.role_id.value),
      p_parent_position_id: parentId,
      p_user_id: form.elements.user_id.value || null,
      p_position_id: id ? Number(id) : null
    };
    if (!payload.p_title || !payload.p_role_id) return notify('Ø¹Ù†ÙˆØ§Ù† Ø³Ù…Øª Ùˆ Ù†Ù‚Ø´ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø§Ù„Ø²Ø§Ù…ÛŒ Ø§Ø³Øª.', true);
    setBusy(button, true);
    try {
      const saved = await rpc('save_organization_position', payload);
      if (!currentSession(actorId, snapshot)) return;
      if (!saved?.position_id) throw new Error('Ø°Ø®ÛŒØ±Ù‡ Ø¬Ø§ÛŒÚ¯Ø§Ù‡ ØªØ£ÛŒÛŒØ¯ Ù†Ø´Ø¯.');
      q('#organizationPositionDialog')?.close();
      await load({ ensureProfiles: false, force: true });
      await window.bamcoOrganizationAccess?.refresh?.({ silent: true });
      if (!currentSession(actorId, snapshot)) return;
      notify('Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø°Ø®ÛŒØ±Ù‡ Ø´Ø¯.');
    } catch (error) {
      notify(error?.message || 'Ø°Ø®ÛŒØ±Ù‡ Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø§Ù†Ø¬Ø§Ù… Ù†Ø´Ø¯.', true);
    } finally {
      setBusy(button, false);
    }
  }

  async function deletePosition(id, button) {
    if (!canManageStructure()) return;
    const item = position(id);
    if (!item) return;
    if (childrenOf(id).length) return notify('Ø§Ø¨ØªØ¯Ø§ Ø¬Ø§ÛŒÚ¯Ø§Ù‡â€ŒÙ‡Ø§ÛŒ Ø²ÛŒØ±Ù…Ø¬Ù…ÙˆØ¹Ù‡ Ø±Ø§ Ø¬Ø§Ø¨Ù‡â€ŒØ¬Ø§ ÛŒØ§ Ø­Ø°Ù Ú©Ù†ÛŒØ¯Ø› Ø­Ø°Ù ÛŒÚ© Ø´Ø§Ø®Ù‡Ù” Ú©Ø§Ù…Ù„ Ø®ÙˆØ¯Ú©Ø§Ø± Ø§Ù†Ø¬Ø§Ù… Ù†Ù…ÛŒâ€ŒØ´ÙˆØ¯.', true);
    if (!await window.bamcoConfirm(`Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Â«${item.title}Â» Ø­Ø°Ù Ø´ÙˆØ¯ØŸ Ø§Ù†ØªØ³Ø§Ø¨ ÙØ±Ø¯ Ø¨Ù‡ Ø§ÛŒÙ† Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ù†ÛŒØ² Ø­Ø°Ù Ù…ÛŒâ€ŒØ´ÙˆØ¯.`)) return;
    setBusy(button, true, 'Ø¯Ø± Ø­Ø§Ù„ Ø­Ø°Ùâ€¦');
    try {
      await removeRows('organization_positions', `id=eq.${encodeURIComponent(id)}`);
      q('#organizationPositionDialog')?.close();
      await load({ ensureProfiles: false, force: true });
      await window.bamcoOrganizationAccess?.refresh?.({ silent: true });
      notify('Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø­Ø°Ù Ø´Ø¯.');
    } catch (error) {
      notify(error?.message || 'Ø­Ø°Ù Ø¬Ø§ÛŒÚ¯Ø§Ù‡ Ø§Ù†Ø¬Ø§Ù… Ù†Ø´Ø¯.', true);
    } finally {
      setBusy(button, false);
    }
  }

  function bindPositionForm() {
    const form = q('#organizationPositionForm');
    if (!form || form.dataset.orgSubmitBound === '1') return;
    form.dataset.orgSubmitBound = '1';
    form.setAttribute('method', 'dialog');
    form.addEventListener('submit', event => { void savePosition(event); });
  }

  function bind() {
    const host = root();
    if (!host || host.dataset.bound === '1') return;
    host.dataset.bound = '1';
    host.addEventListener('click', event => {
      const action = event.target.closest('[data-org-action]')?.dataset.orgAction;
      if (action === 'position') {
        event.preventDefault();
        openPosition();
        return;
      }
      const edit = event.target.closest('[data-org-edit]');
      if (edit) {
        event.preventDefault();
        openPosition(edit.dataset.orgEdit);
        return;
      }
      const remove = event.target.closest('[data-org-delete]');
      if (remove?.dataset.orgDelete) {
        event.preventDefault();
        void deletePosition(remove.dataset.orgDelete, remove);
        return;
      }
      if (event.target.closest('[data-org-close]')) event.target.closest('dialog')?.close();
    });
  }

  function hydrateScopedDirectory(rows) {
    const roles = new Map();
    const positions = new Map();
    const assignments = [];
    for (const row of rows || []) {
      if (!row?.position_id) continue;
      if (row.role_id && !roles.has(String(row.role_id))) roles.set(String(row.role_id), {
        id: row.role_id,
        key: row.role_key,
        title: row.role_title || 'Ø¨Ø¯ÙˆÙ† Ù†Ù‚Ø´',
        level_no: row.role_level_no || 0,
        active: true
      });
      positions.set(String(row.position_id), {
        id: row.position_id,
        title: row.position_title || 'Ø¨Ø¯ÙˆÙ† Ø¹Ù†ÙˆØ§Ù†',
        parent_position_id: row.parent_position_id || null,
        role_id: row.role_id || null,
        active: true
      });
      if (row.occupant_id) assignments.push({
        id: `scope-${row.position_id}`,
        position_id: row.position_id,
        user_id: row.occupant_id,
        is_primary: true,
        valid_to: null
      });
    }
    Object.assign(model, {
      roles: [...roles.values()],
      positions: [...positions.values()],
      assignments,
      loaded: true,
      scoped: true
    });
  }

  async function load({ ensureProfiles = true, force = false } = {}) {
    if (!root() || !state.profile) return;
    if (loading) {
      await loading;
      if (!force) return;
    }
    const job = (async () => {
      try {
        if (canManageStructure()) {
          if (ensureProfiles) await window.bamcoPeople?.refresh?.({ refreshOrganization: false });
          const [roles, positions, assignments] = await Promise.all([
            fetchRows('organization_roles', 'select=*&active=eq.true&order=level_no.asc'),
            fetchRows('organization_positions', 'select=*&active=eq.true&order=title.asc'),
            fetchRows('organization_position_assignments', 'select=*&order=id.desc')
          ]);
          Object.assign(model, { roles, positions, assignments, loaded: true, scoped: false });
        } else {
          await window.bamcoOrganizationAccess?.refresh?.({ silent: true });
          hydrateScopedDirectory(window.bamcoOrganizationAccess?.directory?.() || []);
        }
        render();
        document.dispatchEvent(new CustomEvent('bamco:organization-updated', { detail: model }));
      } catch (error) {
        if (root()) root().innerHTML = `<div class="panel enterprise-error"><b>Ø³Ø§Ø®ØªØ§Ø± Ø³Ø§Ø²Ù…Ø§Ù†ÛŒ Ø¨Ø§Ø±Ú¯Ø°Ø§Ø±ÛŒ Ù†Ø´Ø¯.</b><p>${esc(error?.message || 'Ø®Ø·Ø§ÛŒ Ù†Ø§Ø´Ù†Ø§Ø®ØªÙ‡')}</p><button type="button" class="ghost" data-home-action>Ø¨Ø§Ø²Ú¯Ø´Øª Ø¨Ù‡ Ø®Ø§Ù†Ù‡</button></div>`;
      }
    })();
    loading = job;
    try {
      return await job;
    } finally {
      if (loading === job) loading = null;
    }
  }

  function boot() {
    if (!root()) return;
    render();
    window.BamcoNavigation?.registerView?.('organization', { activate: load });
    // Cards resolve their occupant through BamcoProfiles.  Repaint only the
    // current chart when a display name/avatar revision arrives, rather than
    // retaining a chart-specific person copy.
    document.addEventListener('bamco:profiles-updated', () => {
      if (model.loaded && !root()?.closest('.view')?.classList.contains('hidden')) render();
    });
    document.addEventListener('bamco:domain-invalidated', event => {
      const domain = String(event.detail?.domain || event.detail?.table || '').toLowerCase();
      if (domain === 'organization' && state?.view === 'organization') void load({ ensureProfiles: false, force: true });
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true });
  else boot();
  window.bamcoOrganization = Object.freeze({ load, model, userOrganization });
})();
;

/* source: assets/js/approval-center.js */
/* Central workbench presentation for the organization-based Approval Engine. */
(() => {
  'use strict';
  const E = window.bamcoEnterprise; if (!E) return;
  const { q, fa, notify } = E;
  let filter = 'action', pending = null;
  const route = id => (state.requestRoutes || []).find(item => String(item.request_id) === String(id));
  const allRows = () => [...(state.requests || []), ...(state.requestHistory || [])]
    .filter((item, index, rows) => rows.findIndex(row => String(row.id) === String(item.id)) === index);

  function renderSummary() {
    const host = q('#workbenchSummary'); if (!host) return;
    const current = state.requests || [], history = state.requestHistory || [];
    const values = [
      ['Ø§Ù‚Ø¯Ø§Ù… Ù…Ù†', current.filter(row => route(row.id)?.actionable === true).length],
      ['Ø¯Ø±Ø®ÙˆØ§Ø³Øªâ€ŒÙ‡Ø§ÛŒ Ù…Ù†', allRows().filter(row => String(row.requested_by) === String(state.user?.id)).length],
      ['Ù†ÛŒØ§Ø²Ù…Ù†Ø¯ Ø§ØµÙ„Ø§Ø­', current.filter(row => row.request_status === 'needs_revision' && String(row.requested_by) === String(state.user?.id)).length],
      ['ØªØ£ÛŒÛŒØ¯Ø´Ø¯Ù‡', history.filter(row => row.request_status === 'approved').length]
    ];
    host.innerHTML = values.map(([title, value]) => `<div><b>${fa(value)}</b><span>${title}</span></div>`).join('');
  }
  function sync() {
    if (!q('#approvalsView')) return;
    renderSummary(); q('#approvalsView').classList.toggle('workbench-ready', true);
  }
  async function refreshWorkbench({quiet = false} = {}) {
    if (!state?.token || !state?.profile || pending) return pending;
    const actor = state.user?.id, token = state.token;
    pending = (async () => {
      const workflow = await window.bamcoLoadRequestWorkflow();
      if (actor !== state.user?.id || token !== state.token) return;
      state.requests = workflow.requests;
      state.requestHistory = workflow.history;
      state.requestRoutes = workflow.routes;
      state.definitionRequests = [...workflow.requests, ...workflow.history];
      window.renderRequests?.(); window.renderRequestHistory?.();
      if (state.view === 'dashboard') window.renderDashboard?.();
    })();
    try { await pending; }
    catch (error) { if (!quiet) notify(error.message, true); throw error; }
    finally { pending = null; }
  }
  function relevantInvalidation(detail = {}) {
    const values = Array.isArray(detail.domains) ? detail.domains : [detail.domain, detail.table, detail.entity_type, detail.entityType];
    return values.some(value => /^(workflow|change_requests|organization_workflows|organization_workflow_steps|workflow_steps|notifications)$/i.test(String(value || '')));
  }
  function boot() {
    document.addEventListener('click', event => {
      const tab = event.target.closest('[data-workbench-filter]');
      if (tab) {
        filter = tab.dataset.workbenchFilter;
        qaTabs().forEach(item => item.classList.toggle('active', item === tab));
        window.renderRequests?.();
      }
      if (event.target.closest('#refreshWorkbench')) void refreshWorkbench();
    });
    if (typeof BamcoNavigation !== 'undefined') BamcoNavigation.on('navigation-after', detail => {
      if (detail.to === 'approvals' || detail.to === 'requestHistory') void refreshWorkbench({quiet: true});
    });
    document.addEventListener('bamco:domain-invalidated', event => {
      if (relevantInvalidation(event.detail)) void refreshWorkbench({quiet: true});
    });
    document.addEventListener('bamco:profiles-updated', () => {
      window.renderRequests?.(); window.renderRequestHistory?.();
    });
    window.addEventListener('focus', () => {
      if (!document.hidden && ['approvals', 'requestHistory'].includes(state?.view)) void refreshWorkbench({quiet: true});
    });
  }
  const qaTabs = () => [...document.querySelectorAll('[data-workbench-filter]')];
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, {once: true}); else boot();
  window.bamcoApprovalCenter = {sync, filter: () => filter, refresh: refreshWorkbench, state: () => ({filter})};
  // Transitional event-hook alias only.  It forwards to the single canonical
  // snapshot loader above; it does not restore the old polling/data path.
  window.bamcoRequestSync = Object.freeze({refresh: () => refreshWorkbench()});
})();
;

