  async function load() { if (!root() || !state.profile) return; const request = ++loadVersion; try { const [invoices, payments, projects, parts] = await Promise.all([fetchRows('invoices', 'select=*&order=updated_at.desc,id.desc'), fetchRows('invoice_payments', 'select=*&order=sequence_no.asc'), fetchRows('projects', 'select=id,title&order=title.asc'), fetchRows('parts', 'select=id,fa_name,part_number&order=fa_name.asc')]); if (request !== loadVersion) return; Object.assign(model, { invoices, payments, projects, parts }); if (!model.selected && invoices[0]) model.selected = invoices[0].id; if (model.selected && !invoice(model.selected)) model.selected = invoices[0]?.id || null; render(); } catch (error) { if (request === loadVersion && root()) root().innerHTML = `<div class="panel enterprise-error">${esc(error.message)}</div>`; } }
