  async function exportWorkbook(scope,filtered=false){if(!can(scope,'export'))return deny(scope,'export');const XLSX=await window.ensureBamcoXLSX();const c=CFG[scope],rows=data[scope].selected.size?selectedRows(scope):data[scope].rows,headers=['Ø±Ø¯ÛŒÙ',...c.fields.map(f=>f[1]),...(c.form?['ÙØ±Ù… ØªØ­ÙˆÛŒÙ„ Ø®ÙˆØ¯Ø±Ùˆ']:[])],aoa=[headers,...rows.map((r,i)=>[i+1,...c.fields.map(([key])=>r[key]??''),...(c.form?[r.form_path?'Ø¨Ø§Ø±Ú¯Ø°Ø§Ø±ÛŒ Ø´Ø¯Ù‡':'Ø¨Ø§Ø±Ú¯Ø°Ø§Ø±ÛŒ Ù†Ø´Ø¯Ù‡']:[])])],ws=XLSX.utils.aoa_to_sheet(aoa),wb=XLSX.utils.book_new(),edge={style:'thin',color:{rgb:'FFB8C8C1'}},border={top:edge,bottom:edge,left:edge,right:edge};ws['!views']=[{rightToLeft:true}];ws['!cols']=headers.map(h=>({wch:h.includes('Ù†Ø§Ù… ')||h.includes('Ù…Ø¯Ø§Ø±Ú©')?35:h.includes('ØªÙˆØ¶ÛŒØ­Ø§Øª')?42:Math.max(12,Math.min(25,h.length+4))}));Object.keys(ws).filter(a=>!a.startsWith('!')).forEach(a=>{const cell=ws[a],isHead=/^\D+1$/.test(a);cell.s={font:{name:'B Nazanin',sz:12,bold:isHead,color:{rgb:isHead?'FFFFFFFF':'FF17362D'}},fill:{patternType:'solid',fgColor:{rgb:isHead?'FF176B4D':'FFFFFFFF'}},alignment:{horizontal:'right',vertical:'center',wrapText:true,readingOrder:2},border}});XLSX.utils.book_append_sheet(wb,ws,c.sheet);XLSX.writeFile(wb,`Ø®Ø±ÙˆØ¬ÛŒ ${c.title}.xlsx`);toast(`Ø®Ø±ÙˆØ¬ÛŒ Ø§Ú©Ø³Ù„ ${c.title} Ø¢Ù…Ø§Ø¯Ù‡ Ø´Ø¯.`)}
